class TestAncestryIsTristate:
    def _one(self, recorder, tmp_path, **answers):
        _signal(tmp_path, tasks=[{"name": "t1"}])
        rec = recorder(**answers)
        board = delivery.score_signal(tmp_path, "idea-x", source_dir=tmp_path)
        return rec, board.scores[0]

    def test_exit_128_is_could_not_read_not_delivered_nothing(
        self, recorder, tmp_path
    ):
        _, score = self._one(recorder, tmp_path, ancestor_code=128)
        assert score.verdict is delivery.Verdict.COULD_NOT_READ

    def test_exit_1_is_still_not_an_ancestor(self, recorder, tmp_path):
        _, score = self._one(recorder, tmp_path, ancestor=False)
        assert score.verdict is delivery.Verdict.NOTHING

    def test_a_git_timeout_is_not_exit_1(self, monkeypatch):
        def boom(cmd, **kw):
            raise subprocess.TimeoutExpired(cmd, 1)

        monkeypatch.setattr(delivery.spawn, "run", boom)
        assert delivery._is_ancestor(
            REMOTE_SHA, REMOTE_SHA, cwd=Path("/repo")
        ) is None

    def test_the_tip_is_ensured_once_before_any_task(
        self, recorder, tmp_path
    ):
        _signal(tmp_path, tasks=[{"name": "a"}, {"name": "b"}])
        rec = recorder(have=False)
        delivery.score_signal(tmp_path, "idea-x", source_dir=tmp_path)
        fetches = [c for c in rec.git_calls if c[1] == "fetch"]
        assert fetches and REMOTE_SHA in fetches[0]

    def test_the_diff_is_against_the_first_parent(self, recorder, tmp_path):
        rec, _ = self._one(recorder, tmp_path)
        diffs = [c for c in rec.git_calls if c[1] == "diff"]
        assert diffs
        assert all(any(a.endswith("^1") for a in c) for c in diffs)

    def test_an_unreadable_diff_is_a_skip_not_a_verdict(
        self, recorder, tmp_path
    ):
