"""PR base guard: validator result and the pre-merge re-read."""

import subprocess
from pathlib import Path
from unittest.mock import patch

from runner.core import hooks
from runner.core.hooks import _pr_base_ref, post_hook_validate_pr_target
from runner.core.models import PrTargetResult


def _gh(rc: int, out: str = "", err: str = ""):
    return subprocess.CompletedProcess([], rc, stdout=out, stderr=err)


def _validate(views, edit=None):
    task = {"pr": 7, "base_branch": "umbrella"}
    calls = iter(views if edit is None else [*views, edit])
    with (
        patch("dao_cli.core.project.resolve_task_yaml_path",
              return_value=Path(__file__)),
        patch("dao_cli.core.yaml_io.load_yaml", return_value=task),
        patch.object(hooks, "resolve_auth_env", return_value={}),
        patch.object(hooks, "_run_gh", side_effect=lambda *a, **k: next(calls)),
    ):
        return post_hook_validate_pr_target("t")


def test_ok():
    assert _validate([_gh(0, "umbrella\n")]) == PrTargetResult.OK


def test_fixed():
    assert _validate([_gh(0, "main\n")], _gh(0)) == PrTargetResult.FIXED


def test_mismatch_when_edit_fails():
    assert _validate([_gh(0, "main\n")], _gh(1, err="no")) == PrTargetResult.MISMATCH


def test_unknown_when_unreadable():
    assert _validate([_gh(1, err="boom")]) == PrTargetResult.UNKNOWN


def test_pr_base_ref_empty_is_unreadable():
    with patch.object(hooks, "_run_gh", return_value=_gh(0, "\n")):
        assert _pr_base_ref(1, {})[0] is None
EOF
